function evidence = compute_stage4a6_member_evidence(observed_views,frequency_hz,candidate,cfg,domain,initial_thetas,options)
%COMPUTE_STAGE4A6_MEMBER_EVIDENCE Fit one accepted topology in two domains.
    ib=struct('names',{domain.names},'lower',domain.in_lower,'upper',domain.in_upper);eb=struct('names',{domain.names},'lower',domain.ext_lower,'upper',domain.ext_upper);
    rin=optimize_topology_parameters_bounded(observed_views,frequency_hz,candidate,cfg,ib,initial_thetas,options);rext=optimize_topology_parameters_bounded(observed_views,frequency_hz,candidate,cfg,eb,[rin.theta initial_thetas],options);
    profile=compute_parameter_profile_evidence(rin,rext,domain);boundary=compute_parameter_boundary_evidence(observed_views,frequency_hz,candidate,cfg,rin,domain,options);jac=compute_parameter_jacobian(frequency_hz,candidate,cfg,rext.theta,domain,options);ident=analyze_parameter_identifiability(jac);
    evidence=struct('topology_id',candidate.topology_id,'in_distance',rin.distance,'ext_distance',rext.distance,'in_theta',rin.theta,'ext_theta',rext.theta,'lambda',profile.lambda,'relative_improvement',profile.relative_improvement,'extended_outside',profile.any_extended_parameter_outside,'normalized_parameter_shift',profile.normalized_parameter_shift,'boundary_hit',boundary.boundary_hit,'outward_decrease',boundary.outward_decrease,'minimum_boundary_distance',boundary.minimum_normalized_boundary_distance,'outward_distance_change',boundary.outward_distance_change,'minimum_sensitivity',min(ident.sensitivity_norms),'sensitivity_norms',ident.sensitivity_norms,'singular_values',ident.singular_values,'condition_number',ident.condition_number,'effective_rank',ident.effective_rank,'low_sensitivity',ident.low_sensitivity,'optimization_converged',rin.converged&&rext.converged,'in_optimization',rin,'ext_optimization',rext);
end
